#include <bits/stdc++.h>using namespace std;#define int long long#define double long doublevector<int> answer; void solve(int n, int a) {    if (n == a) {        cout << "YES\n";        cout << answer.size() << "\n";        for (int i = answer.size() - 1; i >= 0; i--) {            cout << answer[i] << " ";        }         return;    } else {        if (n % 10 == 1) {            answer.push_back(n / 10);            solve(n / 10, a);        } else if (n % 2 == 0 && n != 0) {            answer.push_back(n / 2);            solve(n / 2, a);        } else {            cout << "NO" << "\n";            return;        }    }} int32_t main() {    ios::sync_with_stdio(false);    cin.tie(0);    cout.tie(0);    int a, b;    cin >> a >> b;    answer.push_back(b);    solve(b, a);    return 0;}